func (toq *TravelOrderQuery) loadFulfillments(ctx context.Context, query *TravelFulfillmentQuery, nodes []*TravelOrder, init func(*TravelOrder), assign func(*TravelOrder, *TravelFulfillment)) error {
	fks := make([]driver.Value, 0, len(nodes))
	nodeids := make(map[uuid.UUID]*TravelOrder)
	for i := range nodes {
		fks = append(fks, nodes[i].ID)
		nodeids[nodes[i].ID] = nodes[i]
		if init != nil {
			init(nodes[i])
		}
	}
	if len(query.ctx.Fields) > 0 {
		query.ctx.AppendFieldOnce(travelfulfillment.FieldTravelOrderID)
	}
	query.Where(predicate.TravelFulfillment(func(s *sql.Selector) {
		s.Where(sql.InValues(s.C(travelorder.FulfillmentsColumn), fks...))
	}))
	neighbors, err := query.All(ctx)
	if err != nil {
		return err
	}
	for _, n := range neighbors {
		fk := n.TravelOrderID
		node, ok := nodeids[fk]
		if !ok {
			return fmt.Errorf(`unexpected referenced foreign-key "travel_order_id" returned %v for node %v`, fk, n.ID)
		}
		assign(node, n)
	}
	return nil
}

func (toq *TravelOrderQuery) sqlCount(ctx context.Context) (int, error) {
	_spec := toq.querySpec()
	if len(toq.modifiers) > 0 {
		_spec.Modifiers = toq.modifiers
	}
	_spec.Node.Columns = toq.ctx.Fields
	if len(toq.ctx.Fields) > 0 {
		_spec.Unique = toq.ctx.Unique != nil && *toq.ctx.Unique
	}
	return sqlgraph.CountNodes(ctx, toq.driver, _spec)
}

func (toq *TravelOrderQuery) querySpec() *sqlgraph.QuerySpec {
	_spec := sqlgraph.NewQuerySpec(travelorder.Table, travelorder.Columns, sqlgraph.NewFieldSpec(travelorder.FieldID, field.TypeUUID))
	_spec.From = toq.sql
	if unique := toq.ctx.Unique; unique != nil {
		_spec.Unique = *unique
	} else if toq.path != nil {
		_spec.Unique = true
	}
	if fields := toq.ctx.Fields; len(fields) > 0 {
		_spec.Node.Columns = make([]string, 0, len(fields))
		_spec.Node.Columns = append(_spec.Node.Columns, travelorder.FieldID)
		for i := range fields {
			if fields[i] != travelorder.FieldID {
				_spec.Node.Columns = append(_spec.Node.Columns, fields[i])
			}
		}
		if toq.withHotelOffer != nil {
			_spec.Node.AddColumnOnce(travelorder.FieldHotelOfferID)
		}
		if toq.withFlightOffer != nil {
			_spec.Node.AddColumnOnce(travelorder.FieldFlightOfferID)
		}
		if toq.withVacationOffer != nil {
			_spec.Node.AddColumnOnce(travelorder.FieldVacationOfferID)
		}
		if toq.withTrainOffer != nil {
			_spec.Node.AddColumnOnce(travelorder.FieldTrainOfferID)
		}
	}
	if ps := toq.predicates; len(ps) > 0 {
		_spec.Predicate = func(selector *sql.Selector) {
			for i := range ps {
				ps[i](selector)
			}
		}
	}
	if limit := toq.ctx.Limit; limit != nil {
		_spec.Limit = *limit
	}
	if offset := toq.ctx.Offset; offset != nil {
		_spec.Offset = *offset
	}
	if ps := toq.order; len(ps) > 0 {
		_spec.Order = func(selector *sql.Selector) {
			for i := range ps {
				ps[i](selector)
			}
		}
	}
	return _spec
}

func (toq *TravelOrderQuery) sqlQuery(ctx context.Context) *sql.Selector {
	builder := sql.Dialect(toq.driver.Dialect())
	t1 := builder.Table(travelorder.Table)
	columns := toq.ctx.Fields
	if len(columns) == 0 {
		columns = travelorder.Columns
	}
	selector := builder.Select(t1.Columns(columns...)...).From(t1)
	if toq.sql != nil {
		selector = toq.sql
		selector.Select(selector.Columns(columns...)...)
	}
	if toq.ctx.Unique != nil && *toq.ctx.Unique {
		selector.Distinct()
	}
	for _, p := range toq.predicates {
		p(selector)
	}
	for _, p := range toq.order {
		p(selector)
	}
	if offset := toq.ctx.Offset; offset != nil {
		// limit is mandatory for offset clause. We start
		// with default value, and override it below if needed.
		selector.Offset(*offset).Limit(math.MaxInt32)
	}
	if limit := toq.ctx.Limit; limit != nil {
		selector.Limit(*limit)
	}
	return selector
}

// WithNamedFulfillments tells the query-builder to eager-load the nodes that are connected to the "fulfillments"
// edge with the given name. The optional arguments are used to configure the query builder of the edge.
func (toq *TravelOrderQuery) WithNamedFulfillments(name string, opts ...func(*TravelFulfillmentQuery)) *TravelOrderQuery {
	query := (&TravelFulfillmentClient{config: toq.config}).Query()
	for _, opt := range opts {
		opt(query)
	}
	if toq.withNamedFulfillments == nil {
		toq.withNamedFulfillments = make(map[string]*TravelFulfillmentQuery)
	}
	toq.withNamedFulfillments[name] = query
	return toq
}

